      import { Browser, Page } from 'playwright';
      import { agent } from '@goodfetch/collie-client';
      import { run } from '@goodfetch/collie-client/run';

      interface Quote {
        text: string;
        author: string;
        tag: string;
      }

      async function getQuotes(): Promise<Quote[]> {
        const quotes: Quote[] = [];
        const browser = await playwright.chromium.launch();
        const context = await browser.newContext();
        const page = await context.newPage();

        try {
          await page.goto('https://quotes.toscrape.com/search.aspx');
          await page.selectOption('select#author', 'Albert Einstein');
          await page.waitForNavigation();

          const tags = await page.$$('.tag');
          for (const tag of tags) {
            const tagName = await page.evaluate(el => el.textContent, tag);
            if (tagName === 'inspirational') {
              await tag.click();
              break;
            }
          }

          await page.waitForNavigation();
          const quoteElements = await page.$$('.quote');
          for (const quoteElement of quoteElements) {
            const text = await quoteElement.$eval('.text', el => el.textContent?.trim() || '');
            const author = await quoteElement.$eval('.author', el => el.textContent?.trim() || '');
            const tag = await quoteElement.$eval('.tag', el => el.textContent?.trim() || '');
            quotes.push({ text, author, tag });
          }
        } catch (error) {
          throw new Error('An error occurred while fetching quotes: ' + error.message);
        } finally {
          await browser.close();
        }

        return quotes;
      }

      run(async () => {
        const quotes = await getQuotes();
        if (quotes.length === 0) {
          console.log('No quotes found.');
        } else {
          console.log(quotes);
        }
      });
    `
